"""Source-bound vehicle-to-driveway raw geometry; no statutory reference-point choice."""
import argparse
import hashlib
import json
import math
from pathlib import Path

FRAMES=600
CAMERAS=('overview','approach','reference_corner','driver_reference')


def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()


def rows(path):
    if not path.is_file():raise ValueError('Missing required source: '+path.name)
    data=[json.loads(line) for line in path.read_text().splitlines()]
    if len(data)!=FRAMES:raise ValueError('Original source must contain 600 frames')
    return data


def bbox(points):
    if not isinstance(points,list) or len(points)<4:raise ValueError('Original full vehicle body missing')
    if any(not isinstance(p,list) or len(p)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in p) for p in points):
        raise ValueError('Original body corner invalid')
    return min(p[0] for p in points),max(p[0] for p in points),min(p[1] for p in points),max(p[1] for p in points)


def gap(xmin,xmax,entrance):
    return max(0,entrance['x_min_m']-xmax,xmin-entrance['x_max_m'])


def measure(attempt):
    attempt=Path(attempt);context_path=attempt/'entrance-context.json'
    motion_path=attempt/'native-vehicle.jsonl';frames_path=attempt/'video_frames.jsonl'
    for path in (context_path,motion_path,frames_path):
        if not path.is_file():raise ValueError('Missing required source: '+path.name)
    context=json.loads(context_path.read_text());entrance=context.get('entrance')
    if context.get('source_kind') not in ('original_native','synthetic_diagnostic') or any(context.get(key) is not True for key in
        ('fire_station_identity_reviewed','driveway_entrance_reviewed','highway_side_reviewed')):
        raise ValueError('Original fire-station entrance and road-side identity unreviewed')
    if context['source_kind']=='original_native':
        authority=attempt/'authority/manifest.json'
        if not authority.is_file() or sha(authority)!=context.get('authority_manifest_sha256'):
            raise ValueError('Retained fire-station authority manifest missing or changed')
        source_hashes=context.get('authority_source_sha256') or {}
        for name in ('station_identity','driveway_entrance','highway_boundary','activity_and_directions'):
            retained=attempt/'authority'/(name+'.source')
            if not retained.is_file() or sha(retained)!=source_hashes.get(name):
                raise ValueError('Retained fire-station authority source missing or changed: '+name)
    if not isinstance(entrance,dict) or any(type(entrance.get(k)) not in (int,float) for k in ('x_min_m','x_max_m','road_edge_y_m')):
        raise ValueError('Original entrance extent missing')
    motions,frames=rows(motion_path),rows(frames_path)
    previous=-1;stationary=[];source_sides=set()
    entrance_side=entrance.get('road_side')
    if entrance_side not in ('north','south'):
        raise ValueError('Fire-station entrance road side missing')
    for i,(motion,frame) in enumerate(zip(motions,frames)):
        native=motion.get('native_frame')
        if type(native) is not int or native<=previous or frame.get('native_frame')!=native:
            raise ValueError('Original Native frame join differs')
        previous=native
        if motion.get('video_frame')!=i or frame.get('video_frame')!=i or abs(motion.get('time_s',-1)-i/20)>1e-6 or abs(frame.get('time_s',-1)-i/20)>1e-6:
            raise ValueError('Original video frame/time join differs')
        if frame.get('camera_native_frames')!={name:native for name in CAMERAS}:
            raise ValueError('Original four-camera join differs')
        xmin,xmax,ymin,ymax=bbox(motion.get('body_xy_m'))
        speed=motion.get('speed_mps')
        if type(speed) not in (int,float) or not math.isfinite(speed) or speed<0:
            raise ValueError('Original speed invalid')
        side='south' if (ymin+ymax)/2<0 else 'north'
        source_sides.add(side)
        if speed==0:
            stationary.append({'frame':i,'body_edge_gap_m':gap(xmin,xmax,entrance),
                'body_x_min_m':xmin,'body_x_max_m':xmax,'road_side':side,
                'entrance_side_relation':'same' if side==entrance_side else 'opposite'})
    for name in CAMERAS:
        if not (attempt/(name+'.mkv')).is_file():raise ValueError('Missing required source: '+name+'.mkv')
    by_side={relation:[x['body_edge_gap_m'] for x in stationary if x['entrance_side_relation']==relation]
             for relation in ('same','opposite')}
    return {'format':'c229410-fire-station-entrance-raw-geometry-v2','frame_count':FRAMES,
        'rate_hz':20,'stationary_sample_count':len(stationary),
        'stationary_min_body_edge_gap_m':min((x['body_edge_gap_m'] for x in stationary),default=None),
        'stationary_max_body_edge_gap_m':max((x['body_edge_gap_m'] for x in stationary),default=None),
        'road_sides_seen':sorted(source_sides),'stationary_samples':stationary,
        'stationary_min_gap_by_entrance_side_m':{key:min(value) if value else None for key,value in by_side.items()},
        'initial_activity':context.get('initial_activity'),'exception_context':context.get('exception_context'),
        'parking_activity_reviewed':context.get('parking_activity_reviewed') is True,
        'traffic_conflict_reviewed':context.get('traffic_conflict_reviewed') is True,
        'law_officer_device_direction_reviewed':context.get('law_officer_device_direction_reviewed') is True,
        'statutory_reference_point_method_adopted':False,'twenty_foot_clause_verdict':'unresolved',
        'opposite_side_seventy_five_foot_clause_verdict':'unresolved' if by_side['opposite'] else 'not_measured',
        'legal_verdict_claimed':False,'physical_acceptance_claimed':False,
        'source_sha256':{p.name:sha(p) for p in (context_path,motion_path,frames_path)},
        'camera_video_sha256':{name:sha(attempt/(name+'.mkv')) for name in CAMERAS}}


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--attempt',type=Path,required=True)
    parser.add_argument('--output',type=Path,required=True);args=parser.parse_args()
    if args.output.exists():raise ValueError('Use fresh measurement output')
    value=measure(args.attempt);args.output.write_text(json.dumps(value,indent=2,allow_nan=False)+'\n')
    print(json.dumps({'stationary_min_body_edge_gap_m':value['stationary_min_body_edge_gap_m'],
        'statutory_reference_point_method_adopted':False}))


if __name__=='__main__':main()

"""Read cited fire-station and road facts before Native acquisition."""
import hashlib
import json
import math
from pathlib import Path

FACTS=('station_identity','driveway_entrance','highway_boundary','activity_and_directions')


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def load(path):
    path=Path(path).resolve()
    record=json.loads(path.read_text())
    if record.get('format')!='c229410-authority-context-v1':
        raise ValueError('Fire-station authority context format differs')
    if record.get('state')!='Nevada' or record.get('public_highway') is not True:
        raise ValueError('Cited Nevada public highway fact required')
    extent=record.get('entrance')
    if not isinstance(extent,dict) or any(type(extent.get(k)) not in (int,float) or not math.isfinite(extent[k]) for k in ('x_min_m','x_max_m','road_edge_y_m')):
        raise ValueError('Cited fire-station driveway extent required')
    if extent['x_min_m']>=extent['x_max_m'] or extent.get('road_side') not in ('north','south'):
        raise ValueError('Fire-station driveway side or extent invalid')
    if record.get('initial_activity') not in ('stopped','standing','parked'):
        raise ValueError('Cited initial stop/stand/park activity required')
    if record.get('exception_context') not in ('none','traffic_conflict','law','police_officer','official_device'):
        raise ValueError('Cited exception context required')
    reviews=record.get('fact_reviews')
    if not isinstance(reviews,dict) or any(reviews.get(name) is not True for name in FACTS):
        raise ValueError('Independent review conclusion required for each authority fact')
    sources=record.get('sources')
    if not isinstance(sources,dict) or set(sources)!=set(FACTS):
        raise ValueError('Four cited authority sources required')
    source_paths={}
    for name in FACTS:
        item=sources[name]
        if not isinstance(item,dict) or not item.get('citation') or not item.get('path') or not item.get('sha256'):
            raise ValueError('Incomplete cited source: '+name)
        relative=Path(item['path'])
        if relative.is_absolute():
            raise ValueError('Authority source path must be relative: '+name)
        source=(path.parent/relative).resolve()
        if path.parent not in source.parents or not source.is_file() or sha(source)!=item['sha256']:
            raise ValueError('Authority source missing or changed: '+name)
        source_paths[name]=source
    return {'record':record,'manifest_path':path,'manifest_sha256':sha(path),'source_paths':source_paths}

"""Derive source-qualified context views from retained original files.

The views expose provenance and unresolved facts. They never turn the authored
entrance outline or synthetic fixture into a verified fire station.
"""
import hashlib
import json
from pathlib import Path

SOURCE_NAMES=('station_entrance_source','highway_side_source','traffic_conflict_source',
              'applicable_law_source','police_direction_source','official_device_source')
AUTHORITY_NAMES=('station_identity','driveway_entrance','highway_boundary','activity_and_directions')

def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def _read(path):
    path=Path(path)
    if not path.is_file():
        raise ValueError('Missing original source: '+path.name)
    return json.loads(path.read_text())

def derive(attempt):
    attempt=Path(attempt)
    context=_read(attempt/'entrance-context.json')
    kind=context.get('source_kind')
    if kind not in ('original_native','synthetic_diagnostic'):
        raise ValueError('Unknown entrance context provenance')
    views={name:{'source_kind':kind,'review_status':'unverified'} for name in SOURCE_NAMES}
    if kind=='synthetic_diagnostic':
        for view in views.values():
            view['diagnostic_only']=True
        return views
    manifest=attempt/'authority/manifest.json'
    if sha(manifest)!=context.get('authority_manifest_sha256'):
        raise ValueError('Original authority manifest hash differs')
    authority=_read(manifest)
    sources=authority.get('sources',{})
    if set(sources)!=set(AUTHORITY_NAMES):
        raise ValueError('Original authority source set differs')
    source_hashes={}
    for name in AUTHORITY_NAMES:
        original=attempt/'authority'/(name+'.source')
        expected=sources[name].get('sha256')
        if not original.is_file() or not expected or sha(original)!=expected:
            raise ValueError('Original authority source missing or changed: '+name)
        if context.get('authority_source_sha256',{}).get(name)!=expected:
            raise ValueError('Entrypoint authority source binding differs: '+name)
        source_hashes[name]=expected
    views['station_entrance_source'].update({'review_status':'retained_authority_record',
        'station_identity_sha256':source_hashes['station_identity'],
        'driveway_entrance_sha256':source_hashes['driveway_entrance'],
        'entrance_geometry':context.get('entrance')})
    views['highway_side_source'].update({'review_status':'retained_authority_record',
        'highway_boundary_sha256':source_hashes['highway_boundary'],
        'road_xodr_sha256':sha(attempt/'road.xodr')})
    traffic_path=attempt/'native-vehicle.jsonl'
    if not traffic_path.is_file():
        raise ValueError('Missing original source: native-vehicle.jsonl')
    count=0
    for line in traffic_path.read_text().splitlines():
        if json.loads(line).get('traffic_conflict_vehicle') is not None:
            count+=1
    views['traffic_conflict_source'].update({'review_status':'raw_actor_samples_retained',
        'native_vehicle_sha256':sha(traffic_path),'actor_sample_count':count})
    directions_path=attempt/'authority/activity_and_directions.source'
    try:
        directions=json.loads(directions_path.read_text())
    except (ValueError,UnicodeDecodeError):
        directions={}
    for name,key in (('applicable_law_source','law'),('police_direction_source','police_officer'),
                     ('official_device_source','official_device')):
        item=directions.get(key)
        if isinstance(item,dict) and {'source_id','issued_by','directed_action','valid_time'}<=set(item):
            views[name].update({'review_status':'source_record_retained',
                'authority_sha256':source_hashes['activity_and_directions'],
                'source_record':item})
        else:
            views[name].update({'review_status':'source_record_missing',
                'authority_sha256':source_hashes['activity_and_directions']})
    return views
